import { KEYS, TextApi, createTSlatePlugin } from "platejs";

//#region src/lib/utils/getDraftCommentKey.ts
const getDraftCommentKey = () => `${KEYS.comment}_draft`;

//#endregion
//#region src/lib/utils/isCommentKey.ts
const isCommentKey = (key) => key.startsWith(`${KEYS.comment}_`);

//#endregion
//#region src/lib/utils/getCommentCount.ts
const getCommentCount = (node) => {
	let commentCount = 0;
	Object.keys(node).forEach((key) => {
		if (isCommentKey(key) && key !== getDraftCommentKey()) commentCount++;
	});
	return commentCount;
};

//#endregion
//#region src/lib/utils/getCommentKey.ts
const getCommentKey = (id) => `${KEYS.comment}_${id}`;

//#endregion
//#region src/lib/utils/getCommentKeyId.ts
const getCommentKeyId = (key) => key.replace(`${KEYS.comment}_`, "");

//#endregion
//#region src/lib/utils/getCommentKeys.ts
const getCommentKeys = (node) => {
	const keys = [];
	Object.keys(node).forEach((key) => {
		if (isCommentKey(key)) keys.push(key);
	});
	return keys;
};

//#endregion
//#region src/lib/utils/getTransientCommentKey.ts
/** Do not start with comment_ to avoid conflict with other comment keys */
const getTransientCommentKey = () => `${KEYS.comment}Transient`;

//#endregion
//#region src/lib/utils/isCommentNodeById.ts
/** Whether the node has a comment id. */
const isCommentNodeById = (node, id) => !!node[getCommentKey(id)];

//#endregion
//#region src/lib/withComments.ts
const withComment = ({ editor, tf: { normalizeNode } }) => ({ transforms: { normalizeNode(entry) {
	const [node, path] = entry;
	if (node[KEYS.comment] && !node[getDraftCommentKey()] && getCommentCount(node) < 1) {
		editor.tf.unsetNodes(KEYS.comment, { at: path });
		return;
	}
	return normalizeNode(entry);
} } });

//#endregion
//#region src/lib/BaseCommentPlugin.ts
const BaseCommentPlugin = createTSlatePlugin({
	key: KEYS.comment,
	node: { isLeaf: true },
	rules: { selection: { affinity: "outward" } }
}).overrideEditor(withComment).extendApi(({ editor, type }) => ({
	has: (options) => {
		const { id } = options;
		return (/* @__PURE__ */ new RegExp(`"${getCommentKey(id)}":true`)).test(JSON.stringify(editor.children));
	},
	node: (options = {}) => {
		const { id, isDraft, ...rest } = options;
		return editor.api.node({
			...rest,
			match: (n) => {
				if (isDraft) return n[type] && n[getDraftCommentKey()];
				return id ? isCommentNodeById(n, id) : n[type];
			}
		});
	},
	nodeId: (leaf) => {
		const ids = [];
		const keys = Object.keys(leaf);
		if (keys.includes(getDraftCommentKey())) return;
		keys.forEach((key) => {
			if (!isCommentKey(key) || key === getDraftCommentKey()) return;
			const id = getCommentKeyId(key);
			ids.push(id);
		});
		return ids.at(-1);
	},
	nodes: (options = {}) => {
		const { id, isDraft, transient, ...rest } = options;
		return [...editor.api.nodes({
			...rest,
			match: (n) => {
				if (isDraft) return n[type] && n[getDraftCommentKey()];
				if (transient) return n[type] && n[getTransientCommentKey()];
				return id ? isCommentNodeById(n, id) : n[type];
			}
		})];
	}
})).extendTransforms(({ api, editor, tf, type }) => ({
	removeMark: () => {
		const nodeEntry = api.comment.node();
		if (!nodeEntry) return;
		const keys = getCommentKeys(nodeEntry[0]);
		editor.tf.withoutNormalizing(() => {
			keys.forEach((key) => {
				editor.tf.removeMark(key);
			});
			editor.tf.removeMark(KEYS.comment);
		});
	},
	setDraft: (options = {}) => {
		tf.setNodes({
			[getDraftCommentKey()]: true,
			[type]: true
		}, {
			match: TextApi.isText,
			split: true,
			...options
		});
	},
	unsetMark: (options) => {
		const { id, transient } = options;
		const nodes = api.comment.nodes({
			id,
			at: [],
			transient
		});
		if (!nodes) return;
		nodes.forEach(([node]) => {
			const isOverlapping = getCommentCount(node) > 1;
			let unsetKeys = [];
			const removedId = id ?? api.comment.nodeId(node);
			if (isOverlapping) unsetKeys = [
				getDraftCommentKey(),
				getCommentKey(removedId),
				getTransientCommentKey()
			];
			else unsetKeys = [
				KEYS.comment,
				getDraftCommentKey(),
				getCommentKey(removedId),
				getTransientCommentKey()
			];
			editor.tf.unsetNodes(unsetKeys, {
				at: [],
				match: (n) => n === node
			});
		});
	}
}));

//#endregion
export { getCommentKeys as a, getCommentCount as c, getTransientCommentKey as i, isCommentKey as l, withComment as n, getCommentKeyId as o, isCommentNodeById as r, getCommentKey as s, BaseCommentPlugin as t, getDraftCommentKey as u };